/**
 * KaTeX ships its layout *and* its math fonts as a stylesheet; without it the
 * HTML it produces is unstyled spans (the formulas are effectively invisible).
 * The renderer therefore injects the stylesheet on first use.  The default is
 * the jsDelivr copy of the installed version; self-hosting is
 * `configure_katex_css("./katex/katex.min.css")` (the build writes that file
 * and its `fonts/` next to the bundle).
 */
export declare const DEFAULT_KATEX_CSS_URL: string;
/** Point the KaTeX stylesheet somewhere else (a local path), or pass null to
 *  disable injection entirely (the embedder loads the CSS itself). */
export declare function configure_katex_css(url: string | null): void;
/** The stylesheet URL currently configured, or null when injection is off. */
export declare function katex_css_url(): string | null;
/**
 * Inject the KaTeX stylesheet into `doc` once.  Idempotent and a no-op without
 * a DOM or when injection is disabled, so it is safe to call on every renderer
 * construction.
 */
export declare function ensure_katex_styles(doc?: Document | null): boolean;
/** Options accepted by {@link renderKatex} / {@link measureKatex}. */
export interface KatexRenderOptions {
    /** Display (block) style instead of inline style.  Defaults to `false`. */
    display?: boolean;
    /**
     * Throw on unsupported syntax (default `true`).  With `false` KaTeX embeds
     * its own error markup in `html` instead, which is only useful for probes.
     */
    throwOnError?: boolean;
}
/**
 * Options accepted by {@link measureKatex} / {@link measureKatexDom}.
 *
 * `fontPx` is the piece that makes a probe comparable with the payload it
 * predicts: KaTeX's own layout is em-relative, but glyph advances are rounded
 * to layout units, so a probe authored at a different absolute font size can
 * disagree slightly with the render.  Callers pass the exact font size the
 * payload will be rendered with.
 */
export interface KatexMeasureOptions extends KatexRenderOptions {
    /** Font size (px) to author the probe at.  Defaults to {@link KATEX_PROBE_FONT_PX}. */
    fontPx?: number;
}
/** Result of {@link renderKatex}. */
export interface KatexRender {
    /** KaTeX HTML (`output: "html"`, so no duplicate MathML is emitted). */
    html: string;
    /** Height above the baseline, in em. */
    heightEm: number;
    /** Depth below the baseline, in em. */
    depthEm: number;
}
/** Result of {@link measureKatex}. */
export interface KatexMeasurement {
    widthPx: number;
    heightPx: number;
    /** Font size the probe was authored at; divide the pixel sizes by it. */
    fontPx: number;
}
/**
 * Result of {@link measureKatexDom}: {@link KatexMeasurement} plus the distance
 * from the measured box edges to the text baseline.  The baseline is what lets
 * separately typeset expression parts sit on one common line.
 *
 * The reported box is the content's *laid-out extent*, not just its line box:
 * KaTeX positions fraction numerators/denominators (and roots, limits, …) with
 * relatively positioned `vlist` children, which overflow the line box without
 * growing it.  Measuring the line box alone therefore produces a box that is
 * too short and — because a `<foreignObject>` clips its content to its viewport
 * — renders fractions as a flat, cut-off slice.
 */
export interface KatexDomMeasurement extends KatexMeasurement {
    /** Baseline distance from the box's top edge, in px. */
    baselineFromTopPx: number;
    /** Baseline distance from the box's bottom edge, in px. */
    baselineFromBottomPx: number;
    /**
     * Distance the ink overflows *above* the laid-out line box, in px (`0` when
     * the ink is inside it).  A payload must push its content down by this much,
     * otherwise that overflow is clipped.
     */
    inkOverflowTopPx: number;
}
/** Font size (px) the hidden probe element is authored at by default. */
export declare const KATEX_PROBE_FONT_PX = 100;
/** Line height the probe is authored with; matches the native renderer default. */
export declare const KATEX_PROBE_LINE_HEIGHT = 1.2;
/**
 * Typeset `tex` synchronously and return the HTML plus its em metrics.
 *
 * Results are cached per expression/options.  Unsupported syntax throws a
 * `ParseError` naming the expression (see {@link wrapKatexError}); nothing is
 * silently degraded to a different engine.
 */
export declare function renderKatex(tex: string, options?: KatexRenderOptions): KatexRender;
/**
 * Width of `tex` in em, estimated from the symbol widths KaTeX stores in its
 * box tree.
 *
 * This is the fallback for environments without a layout engine (tests, SSR):
 * a real browser measurement is always preferable and is what
 * {@link measureKatex} returns.  Container nodes (fractions, radicals) do not
 * aggregate a width, so the estimate sums the leaf symbols and never reports
 * something absurdly small.
 */
export declare function estimateKatexWidthEm(tex: string, options?: KatexRenderOptions): number;
/** True when a usable document (with a body) exists for DOM measurement. */
export declare function hasDomMeasurement(): boolean;
/**
 * Lay the KaTeX HTML out in a hidden probe element and return its pixel size.
 *
 * The probe is authored at {@link KATEX_PROBE_FONT_PX} (or the caller's
 * `fontPx`) and removed in a `finally` block, so no nodes are ever left behind
 * and repeated calls share a per-expression cache.  Returns `null` when there
 * is no DOM or when the environment has no layout engine (the rectangle comes
 * back empty), in which case callers fall back to the em metrics from
 * {@link renderKatex}.
 */
export declare function measureKatex(tex: string, options?: KatexMeasureOptions): KatexMeasurement | null;
/**
 * Like {@link measureKatex}, but also reports where the baseline sits inside
 * the laid-out box and how far the ink overflows above the line box.
 *
 * A zero-sized `inline-block` marker is laid out on the same line; an
 * inline-block's baseline is its bottom margin edge, so the marker's bottom is
 * the line baseline.  That makes separately measured expressions align on a
 * shared baseline without guessing font metrics, and it is also the reference
 * the renderer positions its content against.
 *
 * The measured box is the union of the line box and the glyph ink (see
 * {@link elementInkBounds}), i.e. exactly the room the browser lays the content
 * out in, so the payload is neither clipped nor padded.
 */
export declare function measureKatexDom(tex: string, options?: KatexMeasureOptions): KatexDomMeasurement | null;
/**
 * Await the browser's font set before measuring.
 *
 * Text/TeX mobjects measure synchronously, so this must be awaited *before*
 * constructing them (the py2js bridge does it as part of its preload step).
 * Without it the first measurement can bake the fallback font's advance widths
 * into the layout.
 *
 * `document.fonts.ready` alone is not enough for math: it only waits for faces
 * that were already *requested*, and nothing has typeset a formula yet at this
 * point, so KaTeX's families are requested explicitly.  Skipping that makes the
 * probe measure the fallback serif (roughly 20% narrower than KaTeX_Main) and
 * every math box come out too small once the real fonts arrive.
 *
 * No-op when there is no document or no `document.fonts`.
 */
export declare function waitForTextFonts(): Promise<void>;
export declare function katex_styles_ready(timeoutMs?: number): Promise<void>;
/** Drop every cache (used by tests; harmless in production). */
export declare function clearKatexCaches(): void;
